BEGIN TRANSACTION;
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "core_batch" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nom" varchar(120) NOT NULL, "description" text NOT NULL, "zip_reference" varchar(100) NOT NULL, "zip_travail" varchar(100) NULL, "nb_images" integer unsigned NOT NULL CHECK ("nb_images" >= 0), "statut" varchar(12) NOT NULL, "score_qualite" real NULL, "rapport" text NULL CHECK ((JSON_VALID("rapport") OR "rapport" IS NULL)), "date_creation" datetime NOT NULL, "date_soumission" datetime NULL, "assigne_a_id" bigint NULL REFERENCES "core_user" ("id") DEFERRABLE INITIALLY DEFERRED, "client_id" bigint NOT NULL REFERENCES "core_client" ("id") DEFERRABLE INITIALLY DEFERRED, "cree_par_id" bigint NOT NULL REFERENCES "core_user" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "batch_score_entre_0_et_100" CHECK (("score_qualite" IS NULL OR ("score_qualite" >= 0.0 AND "score_qualite" <= 100.0))));
CREATE TABLE "core_category" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nom" varchar(80) NOT NULL UNIQUE, "description" text NOT NULL, "donnee_personnelle" bool NOT NULL);
CREATE TABLE "core_client" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nom" varchar(100) NOT NULL UNIQUE, "secteur" varchar(100) NOT NULL, "date_creation" datetime NOT NULL);
CREATE TABLE "core_demandeinscription" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nom" varchar(100) NOT NULL, "email" varchar(254) NOT NULL, "entreprise_souhaitee" varchar(120) NOT NULL, "motivation" text NOT NULL, "statut" varchar(10) NOT NULL, "date_demande" datetime NOT NULL, "traitee_le" datetime NULL, "note_admin" varchar(200) NOT NULL);
CREATE TABLE "core_export" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date" datetime NOT NULL, "nb_images" integer unsigned NOT NULL CHECK ("nb_images" >= 0), "filtre_applique" varchar(200) NOT NULL, "client_id" bigint NULL REFERENCES "core_client" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "core_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_image" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "fichier" varchar(100) NOT NULL, "statut" varchar(10) NOT NULL, "consentement" bool NOT NULL, "largeur" integer unsigned NULL CHECK ("largeur" >= 0), "hauteur" integer unsigned NULL CHECK ("hauteur" >= 0), "date_upload" datetime NOT NULL, "is_deleted" bool NOT NULL, "deleted_at" datetime NULL, "client_id" bigint NOT NULL REFERENCES "core_client" ("id") DEFERRABLE INITIALLY DEFERRED, "uploaded_by_id" bigint NOT NULL REFERENCES "core_user" ("id") DEFERRABLE INITIALLY DEFERRED, "miniature" varchar(100) NULL, "hash_fichier" varchar(64) NOT NULL);
CREATE TABLE "core_image_categories" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "image_id" bigint NOT NULL REFERENCES "core_image" ("id") DEFERRABLE INITIALLY DEFERRED, "category_id" bigint NOT NULL REFERENCES "core_category" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_journalacces" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date" datetime NOT NULL, "evenement" varchar(20) NOT NULL, "identifiant" varchar(150) NOT NULL, "ip" char(39) NULL, "detail" varchar(255) NOT NULL, "utilisateur_id" bigint NULL REFERENCES "core_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_messagecontact" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nom" varchar(100) NOT NULL, "email" varchar(254) NOT NULL, "message" text NOT NULL, "consentement" bool NOT NULL, "traite" bool NOT NULL, "date_envoi" datetime NOT NULL);
CREATE TABLE "core_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "first_name" varchar(150) NOT NULL, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "role" varchar(10) NOT NULL, "client_id" bigint NULL REFERENCES "core_client" ("id") DEFERRABLE INITIALLY DEFERRED, "manager_id" bigint NULL REFERENCES "core_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" bigint NOT NULL REFERENCES "core_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" bigint NOT NULL REFERENCES "core_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "core_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE UNIQUE INDEX "django_content_type_app_label_model_76bd3d3b_uniq" ON "django_content_type" ("app_label", "model");
CREATE UNIQUE INDEX "auth_group_permissions_group_id_permission_id_0cd325b0_uniq" ON "auth_group_permissions" ("group_id", "permission_id");
CREATE INDEX "auth_group_permissions_group_id_b120cbf9" ON "auth_group_permissions" ("group_id");
CREATE INDEX "auth_group_permissions_permission_id_84c5c92e" ON "auth_group_permissions" ("permission_id");
