CREATE INDEX "core_user_groups_group_id_fe8c697f" ON "core_user_groups" ("group_id");
CREATE UNIQUE INDEX "core_user_user_permissions_user_id_permission_id_73ea0daa_uniq" ON "core_user_user_permissions" ("user_id", "permission_id");
CREATE INDEX "core_user_user_permissions_user_id_085123d3" ON "core_user_user_permissions" ("user_id");
CREATE INDEX "core_user_user_permissions_permission_id_35ccf601" ON "core_user_user_permissions" ("permission_id");
CREATE INDEX "core_export_client_id_f8ad0a5d" ON "core_export" ("client_id");
CREATE INDEX "core_export_user_id_b94215ba" ON "core_export" ("user_id");
CREATE UNIQUE INDEX "core_image_categories_image_id_category_id_611d5913_uniq" ON "core_image_categories" ("image_id", "category_id");
CREATE INDEX "core_image_categories_image_id_14d2e594" ON "core_image_categories" ("image_id");
CREATE INDEX "core_image_categories_category_id_2ba78295" ON "core_image_categories" ("category_id");
CREATE INDEX "django_admin_log_content_type_id_c4bce8eb" ON "django_admin_log" ("content_type_id");
CREATE INDEX "django_admin_log_user_id_c564eba6" ON "django_admin_log" ("user_id");
CREATE INDEX "core_user_manager_id_50317793" ON "core_user" ("manager_id");
CREATE INDEX "django_session_expire_date_a5c62663" ON "django_session" ("expire_date");
CREATE INDEX "core_image_client_id_539c3803" ON "core_image" ("client_id");
CREATE INDEX "core_image_uploaded_by_id_851876f6" ON "core_image" ("uploaded_by_id");
CREATE INDEX "export_client_date_idx" ON "core_export" ("client_id", "date" DESC);
CREATE INDEX "image_galerie_idx" ON "core_image" ("client_id", "date_upload" DESC) WHERE NOT "is_deleted";
CREATE INDEX "image_client_statut_idx" ON "core_image" ("client_id", "statut") WHERE NOT "is_deleted";
CREATE INDEX "core_batch_assigne_a_id_ef0d81c7" ON "core_batch" ("assigne_a_id");
CREATE INDEX "core_batch_client_id_7bdab6e2" ON "core_batch" ("client_id");
CREATE INDEX "core_batch_cree_par_id_0faf2225" ON "core_batch" ("cree_par_id");
CREATE UNIQUE INDEX "image_unique_par_client" ON "core_image" ("client_id", "hash_fichier") WHERE NOT "is_deleted";
CREATE INDEX "journal_tentatives_idx" ON "core_journalacces" ("identifiant", "evenement", "date");
CREATE INDEX "journal_date_idx" ON "core_journalacces" ("date");
CREATE INDEX "core_journalacces_utilisateur_id_b843b030" ON "core_journalacces" ("utilisateur_id");
DELETE FROM "sqlite_sequence";
COMMIT;
